#!/usr/bin/env python3
"""MIT. Exact norm inequalities generated by separation; floating LP diagnostic."""
import json,time
from pathlib import Path
import numpy as np
from scipy.optimize import linprog
from scipy.sparse import coo_matrix

def solve(case):
 parent=case['parent'];w=np.asarray(case['weights']);anchors=np.asarray(case['anchors'],dtype=float);points=np.asarray(case['points'],dtype=float)
 a=len(anchors);k=len(points);d=len(parent);li=k*d
 xs=np.concatenate((anchors,points));pairs=[(i,j) for i in range(a+k) for j in range(max(a,i+1),a+k)]
 ia=np.array([i for i,j in pairs]);ja=np.array([j for i,j in pairs]);dist=np.sum(np.abs(xs[ia]-xs[ja])*w,axis=1)
 rr=[];cc=[];vv=[];rhs=[];seen=set();start=time.monotonic()
 def add(v,b):
  index=len(rhs)
  for c,z in v.items():
   if z:rr.append(index);cc.append(c);vv.append(z)
  rhs.append(b)
 for i in range(k):
  for e in range(d):
   row={i*d+e:-1}
   for f,p in enumerate(parent):
    if p==e:row[i*d+f]=1
   add(row,0)
 def cut(pairindex,signs):
  key=(int(pairindex),tuple(int(s) for s in signs))
  if key in seen:return
  seen.add(key);i,j=pairs[pairindex];row={li:-dist[pairindex]};const=0
  for e,s in enumerate(signs):
   if i<a:const+=s*w[e]*anchors[i,e]
   else:row[(i-a)*d+e]=s*w[e]
   row[(j-a)*d+e]=-s*w[e]
  add(row,-const)
 for idx in range(len(pairs)):cut(idx,np.where(xs[ia[idx]]-xs[ja[idx]]>=0,1,-1))
 obj=np.zeros(li+1);obj[li]=1;bounds=[(0,None)]*li+[(1,None)]
 for iteration in range(80):
  left=60-(time.monotonic()-start)
  if left<=0:return {'status':'budget_elapsed','iterations':iteration,'cuts':len(seen)}
  mat=coo_matrix((vv,(rr,cc)),shape=(len(rhs),li+1)).tocsr()
  result=linprog(obj,A_ub=mat,b_ub=rhs,bounds=bounds,method='highs',options={'time_limit':left})
  if not result.success:return {'status':int(result.status),'message':result.message,'iterations':iteration,'cuts':len(seen)}
  q=result.x[:li].reshape((k,d));L=float(result.fun);ys=np.concatenate((anchors,q));diff=ys[ia]-ys[ja]
  norms=np.sum(np.abs(diff)*w,axis=1);violation=norms-L*dist
  bad=np.flatnonzero(violation>1e-8)
  if not len(bad):
   cone=max([0]+[sum(q[i,f] for f,p in enumerate(parent) if p==e)-q[i,e] for i in range(k) for e in range(d)])
   assert cone<1e-7
   return {'status':0,'minimum_numerical_L':L,'max_pair_ratio':float(np.max(norms/dist)),'max_cone_violation':float(cone),'iterations':iteration+1,'cuts':len(seen),'output_flows':q.tolist(),'elapsed_seconds':time.monotonic()-start,'limits':'All pair inequalities checked at returned solution; floating optimization, no exact dual certificate.'}
  old=len(seen)
  for idx in bad:cut(idx,np.where(diff[idx]>=0,1,-1))
  if len(seen)==old:raise RuntimeError('numerical separation stall')
 return {'status':'iteration_limit','iterations':80,'cuts':len(seen)}

if __name__=='__main__':
 for line in (Path(__file__).parent/'structured-results.jsonl').read_text().splitlines():
  case=json.loads(line);result=solve(case)
  print(json.dumps({'name':case['name'],'result':result}),flush=True)
